# Run random searches for order-dependence after fix on 4-5 nodes to ensure stable is invariant.
import itertools, random, pandas as pd
from pgmpy.causal_discovery import PC
from pgmpy.independencies import Independencies

random.seed(0)
vars5 = ['A','B','C','D','E']
pairs = [tuple(sorted(p)) for p in itertools.combinations(vars5,2)]
level0 = [(x,y,()) for x,y in pairs]
level1 = []
for x,y in pairs:
    for z in vars5:
        if z not in (x,y):
            level1.append((x,y,(z,)))

def run(nodes, assertions, max_cond=2):
    df = pd.DataFrame({n:[0,1] for n in nodes})
    ind = Independencies()
    ind.add_assertions(*assertions)
    est = PC(variant='stable', ci_test='independence_match', max_cond_vars=max_cond, show_progress=False)
    est.fit(df, independencies=ind)
    return set(frozenset(e) for e in est.causal_graph_.edges())

for trial in range(200):
    assertions = []
    for a in level0:
        if random.random() < 0.2:
            assertions.append(a)
    for a in level1:
        if random.random() < 0.2:
            assertions.append(a)
    outs = []
    for perm in random.sample(list(itertools.permutations(vars5)), min(6, len(list(itertools.permutations(vars5))))):
        outs.append(tuple(sorted(tuple(sorted(e)) for e in run(list(perm), assertions, max_cond=2))))
    if len(set(outs)) > 1:
        print('still order dependent', trial)
        print(assertions)
        print(outs)
        break
else:
    print('all stable across permutations in', 200, 'trials')
